// Explicit legacy fixtures for regression tests only. Never imported by the application.
import {createOperationalStore} from '../../../interno/operational-store.js';
const remote=createOperationalStore('campaigns');
export const loadCampaigns=()=>false?remote.load():Promise.resolve([]);
import {normalizeTemplate,priceCents,validDate,templates} from '../legacy-catalogs/modelos-cartaz/model.js';
export const STORAGE_KEY='supermercado-promotion-campaigns-v1';
export const localToday=(date=new Date())=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
const clone=v=>JSON.parse(JSON.stringify(v));
const cleanText=(v,max,label)=>{if(typeof v!=='string'||v.length>max)throw Error(`${label}: use até ${max} caracteres.`);return v.trim();};
const displayText=value=>{cleanText(value,300,'Nome no cartaz');return value.trim()?value.replace(/\r\n?/g,'\n'):'';};
const id=()=>globalThis.crypto?.randomUUID?.()||`campaign-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,9)}`;
const validId=v=>typeof v==='string'&&/^[\w-]{1,100}$/.test(v)&&!['__proto__','constructor','prototype'].includes(v);
export function campaignFields(input){const name=cleanText(input.name,100,'Nome');if(!name)throw Error('Informe o nome da campanha.');if(!validDate(input.start)||!validDate(input.end)||input.start>input.end)throw Error('Informe um período válido. A data final deve ser igual ou posterior à inicial.');return {name,start:input.start,end:input.end,notes:cleanText(input.notes??'',4000,'Anotações')};}
export function normalizeItem(item){if(!validId(item.id)||typeof item.productId!=='string')throw Error('Item inválido.');const name=cleanText(item.name,100,'Produto');if(!name||!Number.isInteger(item.cents)||item.cents<1||item.cents>999999||!['kg','unid'].includes(item.unit))throw Error('Produto, preço ou unidade inválidos.');if(!Number.isInteger(item.quantity)||item.quantity<1||item.quantity>100)throw Error('Use uma quantidade inteira de 1 a 100 cartazes por produto.');if(!['individual','two-a4'].includes(item.printLayout))throw Error('Escolha um formato de impressão.');const templateSnapshot=normalizeTemplate(item.templateSnapshot);if(item.printLayout==='two-a4'&&(templateSnapshot.widthMm>148.5||templateSnapshot.heightMm>210))throw Error('Para 2 por A4, o cartaz deve caber em 148,5 × 210 mm, em retrato.');return {id:item.id,productId:item.productId,name,displayName:displayText(item.displayName??''),cents:item.cents,unit:item.unit,templateId:templateSnapshot.id,templateSnapshot,quantity:item.quantity,printLayout:item.printLayout};}
export function normalizeCampaign(input){if(!validId(input.id)||!Array.isArray(input.items)||input.items.length>200)throw Error('Campanha inválida.');const items=input.items.map(normalizeItem);if(new Set(items.map(i=>i.id)).size!==items.length)throw Error('Produtos duplicados no arquivo.');return {id:input.id,...campaignFields(input),items,createdAt:typeof input.createdAt==='string'?input.createdAt:'',updatedAt:typeof input.updatedAt==='string'?input.updatedAt:''};}
export function parseCampaigns(raw){if(typeof raw!=='string'||raw.length>4000000)throw Error('Arquivo de campanhas inválido.');const data=JSON.parse(raw);if(data.version!==1||!Array.isArray(data.campaigns)||data.campaigns.length>300)throw Error('Arquivo de campanhas inválido.');const campaigns=data.campaigns.map(normalizeCampaign);if(new Set(campaigns.map(c=>c.id)).size!==campaigns.length)throw Error('Campanhas duplicadas.');return campaigns;}
export const campaignStatus=(campaign,today=localToday())=>campaign.end<today?'finished':'active';
const normalize=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR');
export function campaignPage(campaigns,{query='',start='',end='',tab='active',page=1,today=localToday()}={}){if((start&&!validDate(start))||(end&&!validDate(end))||(start&&end&&start>end))throw Error('Informe um período de busca válido.');const q=normalize(query).trim();const found=campaigns.filter(c=>campaignStatus(c,today)===tab&&(!q||normalize(`${c.name} ${c.notes}`).includes(q))&&(!start||c.end>=start)&&(!end||c.start<=end));const pages=Math.max(1,Math.ceil(found.length/12)),current=Math.max(1,Math.min(pages,Number.isFinite(Number(page))?Math.floor(Number(page)):1));return {items:found.slice((current-1)*12,current*12),total:found.length,page:current,pages};}
export function createCampaignStore(storage=null){const listeners=new Set();let campaigns=[],warning='',blocked=false;try{const raw=storage?.getItem(STORAGE_KEY);if(raw)campaigns=parseCampaigns(raw);}catch{warning='Não foi possível ler as campanhas salvas neste navegador. Recarregue a página antes de tentar salvar.';blocked=true;}
const commit=next=>{if(blocked)throw Error(warning);const normalized=next.map(normalizeCampaign);const serialized=JSON.stringify({version:1,campaigns:normalized});if(serialized.length>4000000)throw Error('O limite de armazenamento das campanhas foi atingido.');if(storage){try{storage.setItem(STORAGE_KEY,serialized);}catch{throw Error('Não foi possível salvar. Verifique o espaço e a permissão de armazenamento do navegador.');}}else if(typeof window!=='undefined')throw Error('O navegador não permite salvar as campanhas.');campaigns=normalized;for(const listener of listeners){try{listener();}catch{}};};
const get=id=>{const campaign=campaigns.find(c=>c.id===id);if(!campaign)throw Error('Campanha não encontrada.');return clone(campaign);};
const update=(campaignId,change)=>{const current=get(campaignId);const next=normalizeCampaign({...current,...change,id:current.id,updatedAt:new Date().toISOString()});commit(campaigns.map(c=>c.id===campaignId?next:c));return clone(next);};
return {get,list:()=>clone(campaigns),subscribe(listener){listeners.add(listener);return ()=>listeners.delete(listener);},get warning(){return warning;},create(input){if(campaigns.length>=300)throw Error('Limite de 300 campanhas atingido.');const now=new Date().toISOString(),campaign={id:id(),...campaignFields(input),items:[],createdAt:now,updatedAt:now};commit([campaign,...campaigns]);return clone(campaign);},update(campaignId,input){return update(campaignId,campaignFields(input));},addItem(campaignId,input,products){const campaign=get(campaignId);if(campaign.items.length>=200)throw Error('Limite de 200 produtos por campanha.');const product=products.find(p=>p.id===input.productId);if(!product)throw Error('Selecione um produto do catálogo.');const template=input.templateId?templates.find(t=>t.id===input.templateId):templates[0];if(!template)throw Error('Cadastre um modelo de cartaz.');const item=normalizeItem({id:id(),productId:product.id,name:product.name,cents:priceCents(input.price),unit:input.unit,templateSnapshot:template,quantity:1,printLayout:'individual'});return update(campaignId,{items:[...campaign.items,item]});},updateItem(campaignId,itemId,input){const campaign=get(campaignId),old=campaign.items.find(i=>i.id===itemId);if(!old)throw Error('Produto não encontrado.');const patch={...input};if('price'in patch){patch.cents=priceCents(patch.price);delete patch.price;}if('quantity'in patch){const raw=String(patch.quantity);if(!/^\d+$/.test(raw))throw Error('Informe uma quantidade inteira de 1 a 100.');patch.quantity=Number(raw);}if('templateId'in patch){const t=templates.find(t=>t.id===patch.templateId);if(!t)throw Error('Modelo não encontrado.');patch.templateSnapshot=t;}const next=normalizeItem({...old,...patch,id:old.id,productId:old.productId,name:old.name});return update(campaignId,{items:campaign.items.map(i=>i.id===itemId?next:i)});},removeItem(campaignId,itemId){const campaign=get(campaignId);return update(campaignId,{items:campaign.items.filter(i=>i.id!==itemId)});}};}
let storage=null;try{storage=globalThis.localStorage??null;}catch{}
const localCampaigns=createCampaignStore(storage),listeners=new Set();
const run=async(action,id,payload)=>{const saved=await remote.run(action,id,payload);for(const listener of listeners)listener();return saved;};
const remoteCampaigns={get:id=>remote.get(id),list:()=>remote.list(),warning:'',subscribe(listener){listeners.add(listener);return ()=>listeners.delete(listener);},
 create:input=>run('create',null,input),update:(id,input)=>run('update',id,input),
 addItem:(id,input)=>run('addItem',id,{...input,templateId:input.templateId||templates[0]?.id}),updateItem:(id,itemId,input)=>run('updateItem',id,{itemId,input}),removeItem:(id,itemId)=>run('removeItem',id,{itemId})};
export const campaignStore=new Proxy({}, {get:(_,key)=>(false?remoteCampaigns:localCampaigns)[key]});

export const readCampaigns=()=>campaignStore.list();
export const subscribeCampaigns=listener=>campaignStore.subscribe(listener);
